function showSource(c,returnId,node){sourceContext={cid,y:window.scrollY,tab:resultView,scroll:panelScroller(resultView).scrollTop,button:node?.querySelector('button')||document.activeElement};sourceReturnId=returnId;sourceReturnNode=node;sourceReturnTab=resultView;sourceActive=true;document.querySelectorAll('[data-work-panel]').forEach(p=>p.hidden=true);$('source-panel').hidden=false;$('source-meta').textContent=[c.filename,c.location|| (c.page?'第'+c.page+'页':c.line_start?'第'+c.line_start+(c.line_end&&c.line_end!==c.line_start?'-'+c.line_end:'')+'行':c.origin==='user'?'用户陈述':'来源定位不可用'),c.kind==='legal'?'法律参考（适用性未核验）':''].filter(Boolean).join(' · ');$('source-quote').textContent=c.quote||'没有可展示的引句';$('source-limitation').textContent='引文存在只表示原句可在所选来源中核对，不证明其真实性，也不证明它支持相应结论。'+(c.extraction_scope?' '+c.extraction_scope:'')+(c.parse_warnings?.length?' 未读取范围：'+c.parse_warnings.join('；'):'');const content=$('source-content');content.replaceChildren();const file=c.file_id&&(state.files||[]).find(f=>f.id===c.file_id);if(c.file_id&&!file){content.append(el('p','此来源不属于当前咨询或已不可用，无法打开。','source-unavailable'))}else if(!c.file_id){const message=(state.messages||[]).find(m=>m.id===c.source_id)||[...(state.responses||[]),...(state.outcomes||[])].find(m=>'P-'+m.id===c.source_id);if(message){const block=el('div',undefined,'source-segment');const matched=markQuote(block,message.text,c.quote);content.append(el('p','用户陈述原文','source-page-label'),block);if(!matched)content.append(el('p','原陈述中没有与引句完全匹配的文字，未作高亮。','source-unavailable'))}else content.append(el('p','用户陈述原文不可用。','source-unavailable'))}else{const segments=(file.segments||[]).filter(s=>c.location?file.id+':'+s.part===c.source_id:c.page?s.page===c.page:c.line_start?(s.line_end||s.line_start)>=c.line_start&&(s.line_start||0)<=(c.line_end||c.line_start):false);const exact=segments.find(s=>c.quote&&s.text.includes(c.quote));if(file.name.toLowerCase().endsWith('.pdf')&&c.page){const frame=el('iframe');frame.title=file.name+' 第'+c.page+'页原文';frame.loading='lazy';frame.src=url('files/'+encodeURIComponent(file.id))+'#page='+encodeURIComponent(c.page);content.append(frame);if(exact){const excerpt=el('div',undefined,'source-segment');markQuote(excerpt,exact.text,c.quote);content.append(el('p','解析文本摘录 · 第'+c.page+'页','source-page-label'),excerpt)}else content.append(el('p','已定位到页码；当前解析片段中没有与引句完全匹配的文本，不显示伪造高亮。','source-unavailable'))}else if(segments.length){for(const segment of segments){const block=el('div',undefined,'source-segment'),location=segment.location||(segment.line_start?'第'+segment.line_start+(segment.line_end&&segment.line_end!==segment.line_start?'-'+segment.line_end:'')+'行':'文本片段');block.append(el('span',location,'label'));const text=el('div');if(segment.text.includes(c.quote||'\u0000'))markQuote(text,segment.text,c.quote);else text.textContent=segment.text;block.append(text);content.append(block)}if(!exact)content.append(el('p','已定位到文本片段；提取内容中没有与引句完全匹配的文本，未作高亮。','source-unavailable'))}else content.append(el('p','来源仍属于本次咨询，但未找到对应的已解析位置。','source-unavailable'))}$('source-panel').scrollTop=0;const back=$('source-back');back.focus({preventScroll:true})}
