async function recordResponse(){const text=prompt('写下对方回应或“没有回复”。这是你的记录，系统不会替你发送。');if(text===null||!text.trim())return;const lower=text.toLowerCase();let status='received';if(text.includes('没有回复')||text.includes('未回复'))status='no_reply';else if(text.includes('部分'))status='partial';else if(text.includes('争议'))status='disputed';const waiting=status==='no_reply'?'对方':'';receiveState(await post('response',{text:text.trim(),status,waiting_for:waiting,occurred_at:'',expected_revision:state.revision}));renderWork();note('对方进展已保存；不会自动发送消息。')}
async function recordOutcome(){const text=prompt('记录实际处理结果，例如“房东退回部分押金，剩余争议未解决”。');if(text===null||!text.trim())return;const amountText=prompt('如有已收到金额请输入整数元；未知或不想记录请留空。','');let amount=null;if(amountText&&/^\d+$/.test(amountText.trim()))amount=Number(amountText.trim());let kind=text.includes('部分')?'partial':text.includes('争议')?'disputed':text.includes('收到')||text.includes('到账')?'received':'open';receiveState(await post('outcome',{text:text.trim(),kind,amount,expected_revision:state.revision}));renderWork();note('实际处理结果已保存；金额仅按你的确认记录。')}
