$('add-material').onclick=()=>{$('upload-options').hidden=false;$('add-material').setAttribute('aria-expanded','true');$('file').click()};$('choose-file').onclick=()=>$('file').click();
$('file').onchange=()=>task(async()=>{const f=$('file').files[0];if(!f)return;const owner=cid,kind=$('kind').value,upload={cid:owner,name:f.name,status:'parsing',text:f.name+' · 正在上传与解析…'};pendingUploads.push(upload);renderWork();try{if(!/\.(pdf|docx|txt)$/i.test(f.name))throw Error(/\.doc$/i.test(f.name)?'旧版.doc请另存为.docx或文字PDF，不能只改后缀':'只支持文字PDF、DOCX、UTF-8 TXT');if(f.size>1048576||!f.size)throw Error('文件为空或超过1MiB，本次未导入');const r=await api('upload?name='+encodeURIComponent(f.name)+'&kind='+kind,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f},owner);receiveState(r.state,owner);upload.status='parsed';if(cid===owner){$('upload-options').hidden=true;$('add-material').setAttribute('aria-expanded','false');renderWork()}await refreshList()}catch(e){upload.status='failed';upload.text=f.name+' · 解析失败／未导入：'+e.message;if(cid===owner)renderWork();throw e}finally{if(cid===owner)$('file').value=''}});
