 if(window.ResizeObserver){const observer=new ResizeObserver(scheduleChatSizing);for(const selector of ['#main','.nav','.work-head','.work-tabs','#next-step','.composer-card','.composer-context'])observer.observe(document.querySelector(selector))}
 window.addEventListener('resize',scheduleChatSizing);
